INSERT INTO public.track_tournament_result(id_tournament,id_user,id_record,time,rank,points,date_created,date_updated) SELECT $1,id_user,id,time,1,1000,clock_timestamp(),clock_timestamp() FROM eligible_tournament_winners ON CONFLICT(id_tournament,id_user) DO UPDATE SET id_record=excluded.id_record,time=excluded.time,date_updated=clock_timestamp() WHERE ROW(track_tournament_result.id_record,track_tournament_result.time) IS DISTINCT FROM ROW(excluded.id_record,excluded.time)
